/**
 * Bounds for automatically continued work. The total-step limit is cumulative across every invocation that continues
 * the same durable objective; the wall-clock limit bounds one active invocation. Progress detection remains a separate
 * early-stop mechanism, not a substitute for these hard ceilings.
 */
export interface ContinuationBudget {
  /** Maximum steps for one objective across runs and resumes (STEP_BUDGET_EXHAUSTED). */
  maxTotalSteps: number;
  /** Maximum tool dispatches for one objective across turns and resumes. */
  maxToolInvocations?: number;
  /** Maximum inference requests for one objective across turns and resumes. */
  maxInferenceSubmissions?: number;
  /** Maximum wall-clock minutes for one invocation (TIME_BUDGET_EXHAUSTED). */
  maxTurnMinutes: number;
  /**
   * Consecutive steps without observed progress before the turn stops (STAGNATION_DETECTED). A repeated-state
   * threshold, not a task length: any progressing step resets it (core/execution_tracking.ts defines progress).
   */
  stagnationSteps: number;
  /** Recovery notes the agent may inject for a repeated identical action before stopping (bounded recovery). */
  maxRecoveries: number;
  /** Times the agent may be asked to continue when it stops with acceptance requirements still open. */
  maxCompletionNudges: number;
  /**
   * Consecutive failed verifier attempts on changing candidates that stop the turn as VERIFIER_NOT_CONVERGING when they
   * show the same failure, an A/B alternation or a rising failing-test count (default 3, NEXUS_VERIFIER_CONVERGENCE_ATTEMPTS).
   */
  verifierConvergenceAttempts?: number;
}

/** Hard upper bounds keep an operator override finite even when a config or direct API caller bypasses CLI parsing. */
export const MAX_CONTINUATION_STEPS = 5_000;
export const MAX_CONTINUATION_MINUTES = 4_320;
export const DEFAULT_MAX_TOOL_INVOCATIONS = 1_000;
export const MAX_TOOL_INVOCATIONS = 10_000;
export const DEFAULT_MAX_INFERENCE_SUBMISSIONS = 1_000;
export const MAX_INFERENCE_SUBMISSIONS = 10_000;

export function assertValidContinuationBudget(budget: ContinuationBudget | undefined): void {
  if (!budget) return;
  if (!Number.isSafeInteger(budget.maxTotalSteps) || budget.maxTotalSteps < 1 || budget.maxTotalSteps > MAX_CONTINUATION_STEPS) {
    throw new Error(`Invalid continuation step budget: expected an integer from 1 to ${MAX_CONTINUATION_STEPS}.`);
  }
  if (!Number.isFinite(budget.maxTurnMinutes) || budget.maxTurnMinutes < 1 / 60 || budget.maxTurnMinutes > MAX_CONTINUATION_MINUTES) {
    throw new Error(`Invalid continuation time budget: expected a finite value from 1 second to ${MAX_CONTINUATION_MINUTES} minutes.`);
  }
  if (budget.maxToolInvocations !== undefined && (!Number.isSafeInteger(budget.maxToolInvocations) || budget.maxToolInvocations < 1 || budget.maxToolInvocations > MAX_TOOL_INVOCATIONS)) {
    throw new Error(`Invalid tool invocation budget: expected an integer from 1 to ${MAX_TOOL_INVOCATIONS}.`);
  }
  if (budget.maxInferenceSubmissions !== undefined && (!Number.isSafeInteger(budget.maxInferenceSubmissions) || budget.maxInferenceSubmissions < 1 || budget.maxInferenceSubmissions > MAX_INFERENCE_SUBMISSIONS)) {
    throw new Error(`Invalid inference submission budget: expected an integer from 1 to ${MAX_INFERENCE_SUBMISSIONS}.`);
  }
}

