import pc from "picocolors";
import { getBuildIdentity } from "./build_identity.js";
import { normalizeTrustedDeliverableFiles } from "./config.js";
import { JobRunner, loadJobOperation, readReceipt, readRunnerInfo, requestRefusal, RunnerBusyError, runnerAlive, specDigest, submissionProblem, submitRequest, unattendedSpec } from "./core/job_runner.js";
import { runJobWorker } from "./core/job_worker.js";
import { planOperationGit } from "./core/operation_git.js";
import { DEFAULT_JOB_BUDGETS, isTerminal, newJobIds, parseJobBudgets, parseJobSubmission, readJob, runnerPaths, RunnerStoreError, type JobBudgets, type JobRecord, type JobSubmission, type RunnerPaths } from "./core/runner_store.js";
import { OperationSpecError } from "./operation_cli.js";
import { safeTerminal } from "./ui.js";
import { gitOut } from "./worktrunk/git.js";

/** How long a client waits for the runner to accept a request. */
const ACK_WAIT_MS = 10_000;
