  }
  try {
    return JSON.parse(fs.readFileSync(path.resolve(specPath!), "utf8"));
  } catch (error: any) {
    throw new OperationSpecError(`cannot read operation spec ${specPath}: ${String(error?.message ?? error)}`);
  }
}

