}

const EXIT_OF: Record<string, number> = { COMPLETE: 0, CANCELLED: 130 };

/** Prints the job's event log as it grows until the job ends; returns the ended record. Ending this never ends the job. */
async function follow(paths: RunnerPaths, id: string): Promise<JobRecord> {
  let offset = 0;
  let pending = "";
  const drain = () => {
    let fd: number;
    try {
      fd = fs.openSync(paths.events(id), fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW);
    } catch {
      return;
    }
    try {
      const buffer = Buffer.alloc(64 * 1024);
      for (let count = fs.readSync(fd, buffer, 0, buffer.length, offset); count > 0; count = fs.readSync(fd, buffer, 0, buffer.length, offset)) {
        offset += count;
        pending += buffer.subarray(0, count).toString("utf8");
      }
    } finally {
      fs.closeSync(fd);
    }
    const lines = pending.split("\n");
    pending = lines.pop() ?? "";
