export interface CliProcess {
  proc: ChildProcess;
  identity: ProcessIdentity | undefined;
  exited: Promise<{ code: number | null; signal: NodeJS.Signals | null }>;
  stdout(): string;
  stderr(): string;
}

export interface RunnerWorld {
  root: string;
  home: string;
  stateDir: string;
  paths: RunnerPaths;
